filldraw(circle(3dir(-30),3),white,linewidth(2));

dot((0,0));
dot(3dir(-30));
dot(6dir(-30));

label("$B$",(0,0),NW);
label("$A$",3dir(-30),NE);
label("$C$",6dir(-30),SE);
[/asy]

