\[\|\mathbf{p} - \mathbf{b}\| = 2 \|\mathbf{p} - \mathbf{a}\|.\]

Notice that we can rewrite the left side:
\begin{align*}
\|\mathbf{p} - \mathbf{b}\| &= 2 \|\mathbf{p} - \mathbf{a}\|\\
\Rightarrow\qquad \|\mathbf{p} - \mathbf{b}\|^2 &= 4 \|\mathbf{p} - \mathbf{a}\|^2\\
&= 4(\mathbf{p}-\mathbf{a})^T(\mathbf{p}-\mathbf{a})\\
&= 4(\mathbf{p}^T\mathbf{p}-2\mathbf{a}^T\mathbf{p}+\mathbf{a}^T\mathbf{a})\\
&= 4(\mathbf{p}^T\mathbf{p}-2\mathbf{a}^T\mathbf{p}+\mathbf{a}^T\mathbf{a})\\
&= 4\mathbf{p}^T\mathbf{p}-8\mathbf{a}^T\mathbf{p}+4\mathbf{a}^T\mathbf{a}
\end{align*}

We also have the expression for the right side is:
\begin{align*}
4\|\mathbf{p} - \mathbf{a}\|^2 &= 4(\mathbf{p} - \mathbf{a})^T(\mathbf{p} - \mathbf{a})\\
&= 4(\mathbf{p}^T\mathbf{p}-2\mathbf{a}^T\mathbf{p}+\mathbf{a}^T\mathbf{a})\\
&= 4\mathbf{p}^T\mathbf{p}-8\mathbf{a}^T\mathbf{p}+4\mathbf{a}^T\mathbf{a}
\end{align*}

Since we want to get the same expression for the left side and right side, we must set:
\begin{align*}
4\mathbf{p}^T\mathbf{p}-8\mathbf{a}^T\mathbf{p}+4\mathbf{a}^T\mathbf{a} &= 4\mathbf{p}^T\mathbf{p}-8\mathbf{a}^T\mathbf{p}+4\mathbf{a}^T\mathbf{a}\\
&= 4(\mathbf{p}^T\mathbf{p}-2\mathbf{a}^T\mathbf{p}+\mathbf{a}^T\mathbf{a})
\end{align*}

Simplifying, we have
\begin{align*}
\mathbf{p}^T\mathbf{p}-2\mathbf{a}^T\mathbf{p}+\mathbf{a}^T\mathbf{a} &= 0\\
\Rightarrow\qquad (\mathbf{p}-\mathbf{a})^T(\mathbf{p}-\mathbf{a}) &= 0\\
\Rightarrow\qquad \mathbf{p}-\mathbf{a} &= \mathbf{0}\\
\Rightarrow\qquad \mathbf{p} &= \mathbf{a}
\end{align*}

The vector $\mathbf{p}$ is always equal to $\mathbf{a}$.

